package com.citacloud.springboot.contacloud.app.views;
import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.multitenancy.*;import com.citacloud.springboot.contacloud.app.security.TenantContext;import com.citacloud.springboot.contacloud.app.services.*;import com.citacloud.springboot.contacloud.app.views.components.*;
import com.vaadin.flow.component.Component;import com.vaadin.flow.component.checkbox.Checkbox;import com.vaadin.flow.component.combobox.ComboBox;import com.vaadin.flow.component.confirmdialog.ConfirmDialog;import com.vaadin.flow.component.dialog.Dialog;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.component.radiobutton.RadioButtonGroup;import com.vaadin.flow.component.textfield.*;import com.vaadin.flow.data.value.ValueChangeMode;import com.vaadin.flow.router.*;import jakarta.annotation.security.PermitAll;import org.springframework.beans.factory.ObjectProvider;import java.util.*;import java.util.stream.Collectors;
@Route(value="empresas",layout=MainLayout.class) @PageTitle("Empresas | ContaCloud") @PermitAll
public class EmpresasView extends VerticalLayout implements BeforeEnterObserver {
    private final EmpresaAdministracionService service;private final EmpresaModuloService modules;private final TenantProvisioningService provisioning;private final DatabaseAllocationService allocation;private final AppGrid<EmpresaResumenDto> grid=new AppGrid<>(EmpresaResumenDto.class);private final TextField buscar=new TextField();private final ComboBox<String> estado=new ComboBox<>();private final AppPagination pagination;
    public EmpresasView(EmpresaAdministracionService service,EmpresaModuloService modules,ObjectProvider<TenantProvisioningService> provisioning,ObjectProvider<DatabaseAllocationService> allocation){this.service=service;this.modules=modules;this.provisioning=provisioning.getIfAvailable();this.allocation=allocation.getIfAvailable();addClassName("cc-page");setPadding(false);setSpacing(false);setWidthFull();var nuevo=new AppActionButton(ActionType.NEW,ButtonSize.MAIN,"Nueva empresa",e->crear());nuevo.setVisible(has("empresas.crear"));add(new AppPageHeader("Empresas","Administra las empresas autorizadas del tenant actual.",nuevo));buscar.setLabel("Buscar");buscar.setPlaceholder("Nombre, código o identificación");buscar.setClearButtonVisible(true);buscar.setValueChangeMode(ValueChangeMode.LAZY);estado.setLabel("Estado");estado.setItems("Todos","Activas","Inactivas");estado.setValue("Todos");configurarGrid();pagination=new AppPagination(r->cargar());buscar.addValueChangeListener(e->{pagination.reset();cargar();});estado.addValueChangeListener(e->{if(pagination!=null){pagination.reset();cargar();}});var filtros=new HorizontalLayout(buscar,estado);filtros.addClassName("cc-filter-bar");filtros.setAlignItems(Alignment.END);add(filtros,grid,pagination);if(has("empresas.ver"))cargar();}
    @Override public void beforeEnter(BeforeEnterEvent event){if(!has("empresas.ver"))event.rerouteTo(DashboardView.class);}
    private void configurarGrid(){grid.addColumn(EmpresaResumenDto::nombre).setHeader("Nombre comercial").setAutoWidth(true);grid.addColumn(EmpresaResumenDto::identificacionFiscal).setHeader("RNC / Identificación").setAutoWidth(true);grid.addColumn(EmpresaResumenDto::modulos).setHeader("Módulos").setAutoWidth(true);grid.addComponentColumn(e->badge(e.activo())).setHeader("Estado");grid.addComponentColumn(this::acciones).setHeader("Acciones").setAutoWidth(true).setFlexGrow(0);}
    private Component acciones(EmpresaResumenDto empresa){var row=new HorizontalLayout();row.setPadding(false);row.setSpacing(false);row.add(new AppActionButton(ActionType.VIEW,ButtonSize.GRID_ACTION,"Ver empresa",e->ver(empresa)));if(has("empresas.configurar_modulos"))row.add(new AppActionButton(ActionType.EDIT,ButtonSize.GRID_ACTION,"Configurar módulos",e->editarModulos(empresa)));if(empresa.activo()&&has("empresas.desactivar"))row.add(new AppActionButton(ActionType.DEACTIVATE,ButtonSize.GRID_ACTION,"Desactivar empresa",e->confirmarDesactivar(empresa)));return row;}
    private void cargar(){if(pagination==null)return;var r=pagination.currentRequest();Boolean active=switch(estado.getValue()==null?"Todos":estado.getValue()){case"Activas"->true;case"Inactivas"->false;default->null;};var page=service.buscar(buscar.getValue(),active,r.page(),r.size());grid.setItems(page.getContent());pagination.setTotal(page.getTotalElements());}
    private void crear(){var d=new Dialog();d.setHeaderTitle("Nueva empresa");d.setWidth("min(940px, 96vw)");var nombre=new TextField("Nombre comercial");nombre.setRequired(true);var razon=new TextField("Razón social");var rnc=new TextField("RNC / Identificación");var telefono=new TextField("Teléfono");var correo=new EmailField("Correo electrónico");var direccion=new TextArea("Dirección");direccion.addClassName("cc-dialog-span-2");var form=new Div(nombre,razon,rnc,telefono,correo,direccion);form.addClassName("cc-dialog-form");Map<String,Checkbox> checks=new LinkedHashMap<>();d.add(new H2("Datos de la empresa"),form);if(has("empresas.configurar_modulos")){var moduleGrid=new Div();moduleGrid.addClassName("cc-company-module-grid");for(ModuloEmpresaDto m:modules.catalogoDisponible()){var c=new Checkbox(m.nombre(),m.core());c.setHelperText(m.descripcion());c.setEnabled(!m.core());checks.put(m.key(),c);moduleGrid.add(c);}d.add(new H2("Módulos y opciones"),moduleGrid);}
        var escenario=new RadioButtonGroup<String>("Tipo de creación");escenario.setItems("Empresa del tenant actual","Nuevo tenant");escenario.setValue("Empresa del tenant actual");escenario.setVisible(provisioning!=null&&allocation!=null);var alojamiento=new Div();alojamiento.addClassName("cc-card");var ayuda=new Paragraph();var modo=new RadioButtonGroup<HostingMode>("Asignación de base");List<HostingMode> modos=new ArrayList<>();modos.add(HostingMode.AUTOMATIC);if(has("empresas.seleccionar_base")){modos.add(HostingMode.MANUAL);modos.add(HostingMode.DEDICATED);}modo.setItems(modos);modo.setItemLabelGenerator(x->switch(x){case AUTOMATIC->"Automática";case MANUAL->"Seleccionar base compartida";case DEDICATED->"Base dedicada";});modo.setValue(HostingMode.AUTOMATIC);var nodo=new ComboBox<DatabaseNode>("Base disponible");nodo.setItemLabelGenerator(x->x.code()+" · "+x.name()+(x.region()==null?"":" · "+x.region()));nodo.setWidthFull();alojamiento.add(new H3("Alojamiento"),ayuda,escenario,modo,nodo);Runnable actualizarAlojamiento=()->{boolean nuevo="Nuevo tenant".equals(escenario.getValue())&&provisioning!=null;ayuda.setText(nuevo?"El nuevo tenant será la unidad de alojamiento de esta empresa.":"Se reutilizará la base ya asignada al tenant actual.");modo.setVisible(nuevo);nodo.setVisible(nuevo&&modo.getValue()!=HostingMode.AUTOMATIC);if(nodo.isVisible()){nodo.clear();nodo.setItems(modo.getValue()==HostingMode.DEDICATED?allocation.eligibleDedicatedNodes():allocation.eligibleSharedNodes());}};escenario.addValueChangeListener(e->actualizarAlojamiento.run());modo.addValueChangeListener(e->actualizarAlojamiento.run());actualizarAlojamiento.run();d.add(new H2("Alojamiento / Base de datos"),alojamiento);
        String idempotencyKey=UUID.randomUUID().toString();d.getFooter().add(new AppActionButton(ActionType.SAVE,ButtonSize.MAIN,"Guardar",e->{try{Set<String> keys=checks.entrySet().stream().filter(x->x.getValue().getValue()).map(Map.Entry::getKey).collect(Collectors.toSet());NuevaEmpresaDto input=new NuevaEmpresaDto(nombre.getValue(),razon.getValue(),rnc.getValue(),telefono.getValue(),correo.getValue(),direccion.getValue(),keys);if("Nuevo tenant".equals(escenario.getValue())&&provisioning!=null){DatabaseNode selected=nodo.getValue();if(modo.getValue()!=HostingMode.AUTOMATIC&&selected==null)throw new ReglaNegocioException("Seleccione una base de datos disponible.");ProvisioningResult result=provisioning.provision(new ProvisionTenantRequest(idempotencyKey,input,keys,modo.getValue(),selected==null?null:selected.id()));d.close();notify("Tenant y empresa creados. Código: "+result.empresaCodigo()+" · Base: "+result.databaseNodeCode());}else{service.crearEnTenantActual(input);d.close();cargar();notify("Empresa creada correctamente.");}}catch(RuntimeException ex){notify(ex.getMessage());}}),new AppActionButton(ActionType.CANCEL,ButtonSize.MAIN,"Cancelar",e->d.close()));d.open();}
    private void editarModulos(EmpresaResumenDto empresa){var d=new Dialog();d.setHeaderTitle("Módulos de "+empresa.nombre());d.setWidth("min(900px, 96vw)");Map<String,Checkbox> checks=new LinkedHashMap<>();var moduleGrid=new Div();moduleGrid.addClassName("cc-company-module-grid");for(ModuloEmpresaDto m:service.modulos(empresa.id())){var c=new Checkbox(m.nombre(),m.habilitado());c.setHelperText(m.descripcion());c.setEnabled(!m.core());checks.put(m.key(),c);moduleGrid.add(c);}d.add(moduleGrid);d.getFooter().add(new AppActionButton(ActionType.SAVE,ButtonSize.MAIN,"Guardar",e->{try{service.configurarModulos(empresa.id(),checks.entrySet().stream().filter(x->x.getValue().getValue()).map(Map.Entry::getKey).collect(Collectors.toSet()));d.close();cargar();notify("Módulos actualizados.");}catch(RuntimeException ex){notify(ex.getMessage());}}),new AppActionButton(ActionType.CANCEL,ButtonSize.MAIN,"Cancelar",e->d.close()));d.open();}
    private void ver(EmpresaResumenDto e){var d=new Dialog();d.setHeaderTitle("Detalle de empresa");d.add(new AppDetailSection("Información").field("Nombre comercial",e.nombre()).field("RNC / Identificación",e.identificacionFiscal()).field("Módulos habilitados",Long.toString(e.modulos())).field("Alojamiento",e.alojamiento()).field("Estado",e.activo()?"Activa":"Inactiva"));d.getFooter().add(new AppActionButton(ActionType.CLOSE,ButtonSize.MAIN,"Cerrar",x->d.close()));d.open();}
    private void confirmarDesactivar(EmpresaResumenDto e){var c=new ConfirmDialog();c.setHeader("Desactivar empresa");c.setText("Los datos se conservarán. ¿Desea desactivar "+e.nombre()+"?");c.setCancelable(true);c.setCancelText("Cancelar");c.setConfirmText("Desactivar");c.setConfirmButtonTheme("error primary");c.addConfirmListener(x->{try{service.desactivar(e.id());cargar();notify("Empresa desactivada.");}catch(RuntimeException ex){notify(ex.getMessage());}});c.open();}
    private static Span badge(boolean active){var s=new Span(active?"Activa":"Inactiva");s.getElement().getThemeList().add("badge "+(active?"success":"contrast"));return s;}private static boolean has(String permission){return TenantContext.principalActual().permisos().contains(permission);}private static void notify(String text){com.vaadin.flow.component.notification.Notification.show(text==null?"No fue posible completar la operación.":text);}
}
